# Precompute knight moves for all cells
adj = {i: knight_moves(i) for i in range(64)}

# Fixed assignments: step -> cell
fixed = {
    0: 0, 2: 27, 3: 21, 10: 16, 11: 1, 19: 24, 21: 3,
    27: 51, 38: 38, 50: 43, 51: 60, 59: 53, 61: 42
}

# Reverse mapping: cell -> step (for fixed cells)
fixed_cell_to_step = {v: k for k, v in fixed.items()}

# Warnsdorff's heuristic: prefer moves to cells with fewer onward moves
def warnsdorff_order(cell, visited):
    moves = [m for m in adj[cell] if m not in visited]
    # Sort by number of onward moves (fewer first)
    moves.sort(key=lambda m: len([n for n in adj[m] if n not in visited]))
    return moves

# Backtracking with Warnsdorff's heuristic
def solve():
    tour = [None] * 64
    visited = set()

    # Set fixed values
    for step, cell in fixed.items():
        tour[step] = cell
        visited.add(cell)

    def backtrack(step):
        if step == 64:
            return True

        if tour[step] is not None:
            # Fixed cell, just verify it's reachable
            if step > 0:
                prev = tour[step - 1]
                if tour[step] not in adj[prev]:
                    return False
            return backtrack(step + 1)

        # Try all valid moves from previous cell
        prev = tour[step - 1]
        candidates = [m for m in adj[prev] if m not in visited]

        # Apply Warnsdorff's heuristic
        candidates.sort(key=lambda m: len([n for n in adj[m] if n not in visited and n not in fixed.values() or (n in fixed.values() and fixed_cell_to_step[n] == step + 1)]))

        for cell in candidates:
            # Check if this cell is fixed for a different step
            if cell in fixed_cell_to_step and fixed_cell_to_step[cell] != step:
                continue

            tour[step] = cell
            visited.add(cell)

            if backtrack(step + 1):
                return True

            tour[step] = None
            visited.remove(cell)

        return False

    if backtrack(1):
        return tour
    return None

result = solve()
if result:
    print("Solution found!")
    print(result)
else:
    print("No solution found with basic backtracking")

# Let's use a SAT solver approach with pysat
from pysat.solvers import Glucose3

def cell_to_pos(cell):
    return (cell // 8, cell % 8)

def pos_to_cell(row, col):
    return row * 8 + col

def knight_moves(cell):
    row, col = cell_to_pos(cell)
    moves = []
    for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
        nr, nc = row + dr, col + dc
        if 0 <= nr < 8 and 0 <= nc < 8:
            moves.append(pos_to_cell(nr, nc))
    return moves

# Precompute knight moves for all cells
adj = {i: knight_moves(i) for i in range(64)}

# Fixed assignments: step -> cell
fixed = {
    0: 0, 2: 27, 3: 21, 10: 16, 11: 1, 19: 24, 21: 3,
    27: 51, 38: 38, 50: 43, 51: 60, 59: 53, 61: 42
}

# Variables: x[s][c] = 1 means step s visits cell c
# We'll use variable numbering: var(s, c) = s * 64 + c + 1

def var(s, c):
    return s * 64 + c + 1

solver = Glucose3()

# Each step visits exactly one cell
for s in range(64):
    # At least one cell
    solver.add_clause([var(s, c) for c in range(64)])
    # At most one cell (pairwise)
    for c1 in range(64):
        for c2 in range(c1+1, 64):
            solver.add_clause([-var(s, c1), -var(s, c2)])

# Each cell is visited exactly once
for c in range(64):
    # At least one step
    solver.add_clause([var(s, c) for s in range(64)])
    # At most one step (pairwise)
    for s1 in range(64):
        for s2 in range(s1+1, 64):
            solver.add_clause([-var(s1, c), -var(s2, c)])

# Consecutive steps must be knight moves
for s in range(63):
    for c in range(64):
        # If step s visits cell c, then step s+1 must visit a knight-move neighbor
        # x[s][c] => OR_{n in adj[c]} x[s+1][n]
        solver.add_clause([-var(s, c)] + [var(s+1, n) for n in adj[c]])

# Fixed assignments
for s, c in fixed.items():
    solver.add_clause([var(s, c)])

print("Solving SAT...")
if solver.solve():
    model = solver.get_model()
    print("SAT!")
    # Extract solution
    tour = [None] * 64
    for lit in model:
        if lit > 0:
            v = lit - 1
            s = v // 64
            c = v % 64
            tour[s] = c
    print(tour)
else:
    print("UNSAT")
